def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "NO"

    # Adjacency list for implication graph
    # Node mapping: variable i (1-indexed) <-> nodes 2*(i-1) and 2*(i-1)+1
    # Node 2*(i-1) represents xi (positive), node 2*(i-1)+1 represents ¬xi (negative)
    adj = [[] for _ in range(2 * m)]

    # Read clauses and build implications
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:k + 1]

        # For each literal in the clause, add edges from all other literals' negations to it
        for j in range(k):
            l = literals[j]
            node = (l - 1) * 2 if l > 0 else (l - 1) * 2 + 1

            for another in range(k):
                if j == another:
                    continue

                lit = literals[another]
                # negation node
                neg_l = -lit
                neg_node = (neg_l - 1) * 2 if neg_l > 0 else (neg_l - 1) * 2 + 1

                adj[neg_node].append(node)

    # Tarjan's algorithm for SCC
    index = [0] * (2 * m)
    low = [0] * (2 * m)
    on_stack = [False] * (2 * m)
    stack = []
    scc_nodes = [-1] * (2 * m)
    index_counter = [0]
    scc_id = [0] * (2 * m)
    scc_count = [0]

    def dfs(u):
        index[u] = low[u] = index_counter[0]
        index_counter[0] += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if index[v] == 0:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], index[v])

        if low[u] == index[u]:
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_count[0]
                if v == u:
                    break
            scc_count[0] += 1

    for i in range(2 * m):
        if index[i] == 0:
            dfs(i)

    # Check for contradictions: if scc_id[2v-2] == scc_id[2v-1], then unsatisfiable
    for v in range(1, m + 1):
        if scc_id[2 * (v - 1)] == scc_id[2 * (v - 1) + 1]:
            return "NO"

    # Build assignment: for each variable, lower scc_id wins
    assignment = []
    for v in range(1, m + 1):
        pos_scc = scc_id[2 * (v - 1)]
        neg_scc = scc_id[2 * (v - 1) + 1]
        if pos_scc < neg_scc:
            assignment.append('1')
        else:
            assignment.append('0')

    return "YES\n" + "".join(assignment)


