def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {}

    def grundy(n):
        if n in memo:
            return memo[n]

        if n == 0:
            return 0

        options = {grundy(n - 1)}

        if n % 2 == 0:
            x = n // 2
            if k % 2 == 1:
                options.add(grundy(x))
            else:
                options.add(0)

        mex = 0
        while mex in options:
            mex += 1

        memo[n] = mex
        return mex

    xor_sum = 0
    for pile in a:
        xor_sum ^= grundy(pile)

    return "Kevin" if xor_sum != 0 else "Nicky"

