def solution(input_string):
    """
    Solves the problem of minimum wall removal to make all rooms rectangular.

    Args:
        input_string: String containing n, m on first line, then n grid lines

    Returns:
        Modified grid string after removing minimum walls needed
    """
    from collections import deque

    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(lines[i]) for i in range(1, n + 1)]

    def check_rooms(current_grid):
        """Check if all '.' rooms are rectangular in current_grid."""
        visited = [[False] * m for _ in range(n)]

        for r in range(n):
            for c in range(m):
                if current_grid[r][c] == '.' and not visited[r][c]:
                    queue = deque([(r, c)])
                    visited[r][c] = True

                    rows_set = {r}
                    cols_set = {c}

                    while queue:
                        cr, cc = queue.popleft()
                        rows_set.add(cr)
                        cols_set.add(cc)

                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if (0 <= nr < n and 0 <= nc < m and 
                                current_grid[nr][nc] == '.' and 
                                not visited[nr][nc]):
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                    min_r = min(rows_set)
                    max_r = max(rows_set)
                    min_c = min(cols_set)
                    max_c = max(cols_set)

                    for rr in range(min_r, max_r + 1):
                        for cc in range(min_c, max_c + 1):
                            if current_grid[rr][cc] != '.':
                                return False
        return True

    # Greedily remove one wall that makes all rooms rectangular
    # If already valid, return as is
    if check_rooms(grid):
        return '\n'.join(''.join(row) for row in grid)

    # Try removing each wall one by one to see if it works
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                grid[i][j] = '.'
