from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_divisors(n):
    divisors = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
        i += 1
    if n > 1:
        divisors.append(n)
    return sorted(divisors)

def get_prime_factors(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def solution(input_data):
    lines = []
    for line in input_data.strip().split('\n'):
        if line.strip():
            lines.append(line.strip())

    if not lines:
        return ""

    t = int(lines[0])
    cases = lines[1:t+1]

    results = []

    for line in cases:
        n = int(line)
        all_divisors = get_divisors(n)

        # Get prime factorization
        factors = get_prime_factors(n)
        num_factors = len(factors)

        if len(all_divisors) <= 1:
            # Only divisors starting from 2 means no valid output
            results.append("")
            results.append("0")
            continue

        # Strategy based on number of prime factors
        # For one prime factor (like 2^k): all divisors divisible by same prime
        if num_factors == 1:
            # All divisors share the same prime factor
            results.append(" ".join(map(str, all_divisors)) + "\n")
            results.append("0\n")

        # For two prime factors (p * q): arrange around n
        elif num_factors == 2:
            # Use pattern that minimizes coprime adjacencies
            # Pattern: small_p, pq, large_p, pq, pq, ... n, n
            # But simpler: just arrange all divisors and count
            order = all_divisors.copy()

            # Build order to connect via shared factors
            result_order = []
            result_order.append(order[0])

            moves = 0
            for i in range(1, len(order)):
                prev = order[i-1]
                curr = order[i]
                if gcd(prev, curr) == 1:
                    moves += 1
                    result_order.append(prev)  # Already added
                    result_order.append(curr)
                else:
                    result_order.append(curr)

            # Add n at end and beginning for circular
            if n not in result_order:
                result_order.insert(0, n)
                result_order.append(n)
                result_order = result_order[1:-1] + [n]

            if result_order:
                results.append(" ".join(map(str, result_order)) + "\n")
                results.append(f"{moves}\n")
            else:
                results.append("\n")
                results.append("0\n")

        # For three or more prime factors
        else:
            # n itself is compatible with everything
            # Arrange using n as hub
            built = []
            built.append(all_divisors[-1])  # n is last in sorted
            for d in all_divisors[:-1]:
                built.append(d)

            if len(built) > 0 and gcd(built[-1], built[0]) == 1:
                insert_count = 1

            results.append(" ".join(map(str, built)) + "\n")
            results.append(f"{insert_count if insert_count > 0 else 0}\n")

    return "\n".join(results)

