MOD = 1000000007

def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    rel = {}

    for line in lines[1:]:
        if not line.strip():
            continue
        a, b, c = map(int, line.split())
        adj[a].append(b)
        adj[b].append(a)
        if c == 1:
            rel[(min(a, b), max(a, b))] = 2  # requires same color (love)
        else:
            rel[(min(a, b), max(a, b))] = 0  # requires different colors (hate)

    # Check if all-love structure is valid (only pairs with love are mentioned)
    all_love = True
    for key in rel:
        if rel[key] != 2:
            all_love = False
            break

    # Check if bipartite structure is valid (pairs consistent with 2-coloring)
    color = [-1] * (n + 1)
    num_components = 0
    valid_bipartite = False

    for start in range(1, n + 1):
        if color[start] == -1:
            num_components += 1
            queue = deque([start])
            color[start] = 0
            is_valid_component = True

            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    edge_key = (min(u, v), max(u, v))
                    if edge_key in rel:
                        must_match = (rel[edge_key] == 2)
                        same_color = color[u] == color[v]

                        if same_color != must_match:
                            is_valid_component = False
                            break

                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            queue.append(v)

                if not is_valid_component:
                    break

            if is_valid_component:
                valid_bipartite = True

    if not valid_bipartite:
        return '1' if all_love else '0'

    if all_love:
        # Both structures are valid
        return str((pow(2, num_components - 1, MOD) + 1) % MOD)
    else:
        return str(pow(2, num_components - 1, MOD)) % MOD

