    def add_edge(u, v, c):
        if (u, v) in cap:
            cap[(u, v)] += c
        else:
            cap[(u, v)] = c
        res[(u, v)] = c
        if (v, u) in cap:
            cap[(v, u)] -= c
        else:
            cap[(v, u)] = -c

    for i in range(n):
        add_edge(source, i + 1, a[i])
        add_edge(i + 1 + n, sink, b[i])

    for i in range(n):
        for j in range(n):
            if i == j or (i, j) in roads:
                add_edge(i + 1, j + 1 + n, float('inf'))

    def bfs():
        parent = {source: None}
        queue = deque([source])
        while queue:
            u = queue.popleft()
            if u == sink:
                break
            for v in range(sink + 1):
                if v not in parent and res.get((u, v), 0) > 0:
                    parent[v] = u
                    queue.append(v)
        return parent

    total_flow = 0

    while True:
        parent = bfs()
        if sink not in parent:
            break
        v = sink
        path_flow = float('inf')
        while parent[v] is not None:
            u = parent[v]
            path_flow = min(path_flow, res.get((u, v), 0))
            v = u
        v = sink
        while parent[v] is not None:
            u = parent[v]
            res[(u, v)] -= path_flow
            res[(v, u)] += path_flow
            v = u
        total_flow += path_flow

    if total_flow != total_need:
        return "NO"

    result = []
    for i in range(n):
        row = [str(cap.get((i + 1, j + 1 + n), 0)) for j in range(n)]
        result.append(" ".join(row))

    return "YES\n" + "\n".join(result)

