def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    seq = list(map(int, lines[1].split()))

    def is_gp(seq):
        n = len(seq)
        if n <= 2:
            return True

        # Check if all zeros
        if all(x == 0 for x in seq):
            return True

        # Find first non-zero
        first = -1
        for i in range(n):
            if seq[i] != 0:
                first = i
                break

        if first == -1:
            return True

        # Edge case: only one non-zero element at end
        if first == n - 1:
            return True

        prev = seq[first]
        curr = seq[first + 1]

        # If zero follows non-zero, check all subsequent are zero
        if curr == 0:
            for i in range(first + 1, n):
                if seq[i] != 0:
                    return False
            return True

        # Check ratio consistency using cross-multiplication
        for i in range(first + 1, n):
            if i >= len(seq):
                break
            if seq[i] * prev != seq[i-1] * curr:
                return False

        return True

    # Check if already GP
    if is_gp(seq):
        return "0\n"

    # Try removing each element
    for i in range(n):
        new_seq = seq[:i] + seq[i+1:]
        if is_gp(new_seq):
            return "1\n"

    return "2\n"

