import math
import random

def dist(p1, p2):
    dx = p1[0] - p2[0]
    dy = p1[1] - p2[1]
    dz = p1[2] - p2[2]
    return math.sqrt(dx*dx + dy*dy + dz*dz)

def dist_sq(p1, p2):
    dx = p1[0] - p2[0]
    dy = p1[1] - p2[1]
    dz = p1[2] - p2[2]
    return dx*dx + dy*dy + dz*dz

def sphere_from_3(p1, p2, p3):
    # Find the circumcenter of the triangle (on plane of 3 points)
    c = (p1[0] + p2[0] + p3[0]) / 3.0, (p1[1] + p2[1] + p3[1]) / 3.0, (p1[2] + p2[2] + p3[2]) / 3.0
    center3D = [c[0], c[1], c[2]]

    # Find bulge factor using perpendicular bisectors
    m1 = [p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]]
    n1 = [p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2]]
    m1_dist = dist_sq(p1, p2)
    n1_dist = dist_sq(p1, p3)

    if dist(p1, p3) < 1e-10:
        return sphere_from_2(p1, p2)

    cross_prod = [
        m1[1]*n1[2] - m1[2]*n1[1],
        m1[2]*n1[0] - m1[0]*n1[2],
        m1[0]*n1[1] - m1[1]*n1[0]
    ]
    cross_len_sq = cross_prod[0]**2 + cross_prod[1]**2 + cross_prod[2]**2

    if cross_len_sq < 1e-12:
        return sphere_from_2(p1, p2)

    o = [
        (m1_dist * (cross_prod[1] * n1[2] - cross_prod[2] * n1[1]) + 
         n1_dist * (cross_prod[2] * m1[1] - cross_prod[1] * m1[2])) / (3 * cross_len_sq),
        (m1_dist * (cross_prod[2] * n1[0] - cross_prod[0] * n1[2]) + 
         n1_dist * (cross_prod[0] * m1[2] - cross_prod[2] * m1[0])) / (3 * cross_len_sq),
        (m1_dist * (cross_prod[0] * n1[1] - cross_prod[1] * n1[0]) + 
         n1_dist * (cross_prod[1] * m1[0] - cross_prod[0] * m1[1])) / (3 * cross_len_sq)
    ]

    center2D = [
        p1[0] + (o[0] - p1[0]) + o[0],
        p1[1] + (o[1] - p1[1]) + o[1],
        p1[2] + (o[2] - p1[2]) + o[2]
    ]

    return [center2D[0], center2D[1], center2D[2], min(dist(center2D, p1), math.sqrt(dist_sq(center2D, p2)/2))]

def sphere_from_3_simple(p1, p2, p3):
    m12 = [p2[0]+(p2[0]-p1[0])/2, p2[1]+(p2[1]-p1[1])/2, p2[2]+(p2[2]-p1[2])/2]
    m13 = [p3[0]+(p3[0]-p1[0])/2, p3[1]+(p3[1]-p1[1])/2, p3[2]+(p3[2]-p1[2])/2]

    center = [(p1[0]+p2[0]+p3[0])/3.0, (p1[1]+p2[1]+p3[1])/3.0, (p1[2]+p2[2]+p3[2])/3.0]

    r = dist(center, p1)
    if dist(center, p2) > r or dist(center, p3) > r + 1e-9:
        return [p1[0], p1[1], p1[2], 0.0]

    return [center[0], center[1], center[2], r]

def sphere_from_4(p1, p2, p3, p4):
    A = []
    b = []

    for i in range(1, 4):
        A.append([2*(p1[0]-a[0]), 2*(p1[1]-a[1]), 2*(p1[2]-a[2])])
        b.append(dist_sq(p1, [0,0,0]) - dist_sq(a, [0,0,0]))
        a = p4 if a == p3 else (p3 if a == p2 else (p2 if True else None))

    A[1][0], A[1][1], A[1][2] = 2*(p1[0]-p3[0]), 2*(p1[1]-p3[1]), 2*(p1[2]-p3[2])
    A[2][0], A[2][1], A[2][2] = 2*(p1[0]-p4[0]), 2*(p1[1]-p4[1]), 2*(p1[2]-p4[2])

    aug = [row[:] + [val] for row, val in zip(A, b)]

    for i in range(3):
        max_row = i
        for k in range(i+1, 3):
            if abs(aug[k][i]) > abs(aug[max_row][i]):
                max_row = k
        aug[i], aug[max_row] = aug[max_row], aug[i]

        if abs(aug[i][i]) < 1e-10:
            continue
        for j in range(i+1, 4):
            mult = aug[j][i] / aug[i][i] if aug[i][i] != 0 else 0
            for col in range(i, 4):
                aug[j][col] -= mult * aug[i][col]

    center = [0.0, 0.0, 0.0]
    for i in range(3):
        if abs(aug[i][i]) > 1e-10:
            center[i] = aug[i][3]
            for j in range(i+1, 3):
                if abs(aug[i][i]) > 1e-12:
                    center[i] -= aug[i][j+1] * center[j] / aug[i][i]
            center[i] /= aug[i][i]

    r_sq = dist_sq(center, p1)
    if r_sq < 1e-20:
        r_sq = 0.0
    r = math.sqrt(r_sq)

    return [center[0], center[1], center[2], r]

