    # if and only if it's a prime p = 2 OR p = 1 (mod 4)
    # This is based on the sum of two squares theorem for primes

    # Sieve to get primes up to sqrt(r)
    limit = int((r + 1) ** 0.5) + 1
    is_prime_small = [True] * (limit + 1)
    is_prime_small[0] = is_prime_small[1] = False

    for i in range(2, int(limit**0.5) + 1):
        if is_prime_small[i]:
            for j in range(i*i, limit + 1, i):
                is_prime_small[j] = False

    small_primes = [i for i in range(2, limit + 1) if is_prime_small[i]]

    def is_prime(num):
        if num <= limit:
            return num > 1 and is_prime_small[num]
        for p in small_primes:
            if p * p > num:
                break
            if num % p == 0:
                return False
        return True

    # Count lucky numbers: primes that are either 2 or congruent to 1 mod 4
