def closest_point_to_origin_dx(x1, y1, x2, y2):
    # Closest point on line segment (x1,y1) to (x2,y2) to origin
    B = x1*x2 + y1*y2
    C = x2*x2 + y2*y2
    t = B / C if C > 1e-9 else 0
    return x1 + t * (x2 - x1), y1 + t * (y2 - y1)

