    for i in range(1, k + 1):
        line = parts[i].split()
        x, y, d, t, e = map(int, line)
        transformers.append((x, y, d, t, e))

    # For each transformer, determine which (r, c) positions it occupies
    # and at what time. A transformer at (cx, cy) will be at position (px, py)
    # when time T = px + py = cx + cy satisfies the cycle condition.

    # Group transformers by the positions they will occupy
    position_transformers = {}  # (r, c) -> list of (energy)
    for i, (x, y, d, start_t, energy) in enumerate(transformers):
        # The 4 cycle positions
        cycle_pos = [
            (x, y),
            (x + d, y - d),
            (x + d, y),
            (x, y + d)
        ]

        # Cycle position offset: 0, 1, 2, 3
        for offset, (px, py) in enumerate(cycle_pos):
            if 0 <= px < n and 0 <= py < m:
                # At time T = px + py = cx + cy
                # Check if transformer is at this position when we reach it
                T = px + py  # When we arrive at (px, py), time is T = px + py
                if T >= start_t and (T - start_t) % 4 == offset:
                    if (px, py) not in position_transformers:
                        position_transformers[(px, py)] = []
                    position_transformers[(px, py)].append(energy)

    INF = float('inf')
    dp = [[INF] * m for _ in range(n)]
    dp[0][0] = 0

    import heapq
    pq = [(0, 0, 0)]  # (cost, r, c)

    path_memo = {(0, 0): 0}

    while pq:
        cost, r, c = heapq.heappop(pq)

        if cost > dp[r][c]:
            continue

        if r == n - 1 and c == m - 1:
            return str(cost)

        # Try moving right
        if c + 1 < m:
            nt = r + (c + 1)
            transform_cost = position_transformers.get((r, c + 1), [])
            new_cost = dp[r][c] + dp[0] if not transform_cost else dp[r][c] + sum(transform_cost)
            # Actually, let me recalculate properly
            new_cost = dp[r][c]
            if (r, c + 1) in position_transformers:
                new_cost += sum(position_transformers[(r, c + 1)])

            if new_cost < dp[r][c + 1]:
                dp[r][c + 1] = new_cost
                heapq.heappush(pq, (new_cost, r, c + 1))

        # Try moving down
        if r + 1 < n:
            transform_cost = position_transformers.get((r + 1, c), [])
            new_cost = dp[r][c]
            if (r + 1, c) in position_transformers:
                new_cost += sum(position_transformers[(r + 1, c)])

            if new_cost < dp[r + 1][c]:
                dp[r + 1][c] = new_cost
                heapq.heappush(pq, (new_cost, r + 1, c))

    return str(dp[n - 1][m - 1])

