    pair_counts = defaultdict(int)
    for j in range(m):
        c1, c2 = S[j], T[j]
        if c1 != c2:
            pair_counts[(c1, c2)] += 1

    # Check if current pair counts form valid pairings
    def is_valid(counts):
        if not counts:
            return True
        for (first, second), cnt in counts.items():
            if (second, first) not in counts or counts[(second, first)] != cnt:
                return False
        return True

    valid_positions = []

    # Check first window (position 1)
    if is_valid(pair_counts):
        valid_positions.append(1)

    # Process sliding window
    # Check positions 2 to n-m+1 (represented as indices 1 to n-m)
    for i in range(1, n - m + 1):
        # Remove character at position i-1
        old_s, old_t = S[i - 1], T[i - 1]
        if old_s != old_t:
            p = (old_s, old_t)
            pair_counts[p] -= 1
            if pair_counts[p] == 0:
                del pair_counts[p]

        # Add character at position i+m-1
        new_s, new_t = S[i + m - 1], T[i + m - 1]
        if new_s != new_t:
            p = (new_s, new_t)
            pair_counts[p] += 1

        if is_valid(pair_counts):
            valid_positions.append(i + 1)

    valid_positions.sort()
    result = [str(len(valid_positions)), ' '.join(map(str, valid_positions))]
    return '\n'.join(result)


