        old_s, old_t = S[i - 1], T[i - 1]
        if old_s != old_t:
            p = (old_s, old_t)
            pair_counts[p] -= 1
            if pair_counts[p] == 0:
                del pair_counts[p]

        # Add character at position i+m-1
        new_s, new_t = S[i + m - 1], T[i + m - 1]
        if new_s != new_t:
            p = (new_s, new_t)
            pair_counts[p] += 1

        if is_valid(pair_counts):
            valid_positions.append(i + 1)

    valid_positions.sort()
    result = [str(len(valid_positions)), ' '.join(map(str, valid_positions))]
    return '\n'.join(result)


