    if not lines or not lines[0]:
        return '\n'

    n, m = map(int, lines[0].split())
    if n <= 0 or m <= 0:
        return '\n'

    # Initialize grid
    grid = [['.' for _ in range(m)] for _ in range(n)]

    # Four orientations of T-polyomino
    shapes = [
        [(0,0), (0,1), (0,2), (1,1), (2,1)],  # Up
        [(0,2), (1,0), (1,1), (1,2), (2,2)],  # Down
        [(0,1), (1,1), (2,0), (2,1), (2,2)],  # Left
        [(0,0), (1,0), (1,1), (1,2), (2,0)]   # Right
    ]

    best_k = -1
    best_solution = []

    def find_first_empty():
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    return r, c
        return None

    def can_place(shape, r_start, c_start):
        for dr, dc in shape:
            nr, nc = r_start + dr, c_start + dc
            if not (0 <= nr < n and 0 <= nc < m):
                return False
            if grid[nr][nc] != '.':
                return False
        return True

    def place(shape, r_start, c_start, ch):
        for dr, dc in shape:
            grid[r_start + dr][c_start + dc] = ch

    def unplace(shape, r_start, c_start):
        for dr, dc in shape:
            grid[r_start + dr][c_start + dc] = '.'

    def backtrack(placed_count):
        nonlocal best_k, best_solution

        empty = find_first_empty()
        if empty is None:
            if placed_count > best_k:
                best_k = placed_count
                best_solution = [row[:] for row in grid]
            return

        r, c = empty
        letter = chr(ord('A') + placed_count)

        for shape in shapes:
            for offset_dr, offset_dc in shape:
                br, bc = r - offset_dr, c - offset_dc

                if can_place(shape, br, bc):
                    place(shape, br, bc, letter)
                    backtrack(placed_count + 1)
                    unplace(shape, br, bc)

    backtrack(0)

    result_parts = [str(best_k) if best_k >= 0 else '0']
    for row in best_solution if best_solution else grid:
        result_parts.append(''.join(row))

    return '\n'.join(result_parts) + '\n'

