                # Try to find a path avoiding previously used vertices
                allowed = set(v for v in range(1, n + 1) if v not in forbidden)
                if not allowed:
                    break

                q = collections.deque([(start, [start])])
                local_used = set([start])
                done = False

                while q and not done:
                    curr, path = q.popleft()

                    if curr == end:
                        paths.append(path + [end])
                        forbidden |= set(path[1:-1])
                        done = True
                        continue

                    for neighbor in adj[curr]:
                        if neighbor in local_used:
                            continue
                        if neighbor in forbidden:
                            continue

                        local_used.add(neighbor)
                        path.append(neighbor)
                        if neighbor == end:
                            paths.append(path)
                            forbidden |= set(path[1:-1])
                            done = True
                            break
                        q.append((neighbor, path))

                if done or not q:
                    break

            if len(paths) >= 3:
                # Check actual vertex disjointness
                valid_paths = []
                all_nodes = [start, end]
                for i, p in enumerate(paths):
                    intermediate = set(p[1:-1])
