        num, steps = queue.popleft()

        if num == 0:
            continue

        # Skip if we've already found a better path
        if steps >= min_steps and num in computed:
            continue

        if num > computed.get(num, float('inf')):
            continue

        computed[num] = steps

        # Convert number to digits
        digits = set(int(d) for d in str(num))

        # Find minimum among all digit subtractions
        new_steps = steps + 1

        # If we found a path with equal or better steps, update our best
        if new_steps < min_steps:
            min_steps = new_steps
            computed[min_steps] = num  # Track this result

        for d in digits:
            if d == 0:
                continue  # Don't subtract 0 (doesn't change number)
            new_num = num - d
            if new_num > 0:  # Don't add 0 to queue, we handle the completion
                queue.append((new_num, new_steps))

    return f"{min_steps}\n"


