import sys
from collections import defaultdict
from functools import lru_cache

MOD = 10**9 + 7

class ExpressionParser:
    def __init__(self, s):
        self.s = s
        self.n = len(s)
        self.pos = [0]  # Use list for mutability in nested functions
        self.memo = {}  # Memoization for range calculations

    def peek(self):
        if self.pos[0] < self.n:
            return self.s[self.pos[0]]
        return None

    def get_number(self):
        j = self.pos[0]
        while self.pos[0] < self.n and self.s[self.pos[0]].isdigit():
            self.pos[0] += 1
        if j == self.pos[0]:
            return 0
        num = int(self.s[j:self.pos[0]])
        return num, len(self.s[j:self.pos[0]])

    def repeat_val(self, val, count, length):
        """Repeat 'val' count times, tracking length"""
        # val already has length 'length'
        # Repeat val 'count' times means concatenating val with itself 'count' times
        total_length = length * count
        remaining = MOD - 1
        multiplier = pow(10, length, MOD)

        result = 0
        for _ in range(count - 1):
            result = (result * multiplier + val) % MOD

        if count > 0:
            result = (result * multiplier + val) % MOD

        return result, total_length

    def range_concat(self, l, r):
        """Compute concatenated string value of numbers l to r"""
        key = (l, r)
        if key in self.memo:
            return self.memo[key]

        if l > r:
            self.memo[key] = (0, 0)
            return (0, 0)

        # For efficiency, handle large ranges by digit grouping
        # But for correctness and simplicity, handle all ranges directly

        total_val = 0
        total_len = 0

        def count_digits(n):
            return len(str(n))

        for num in range(l, r + 1):
            d = count_digits(num)
            total_val = (total_val * pow(10, d, MOD) + num) % MOD
            total_len += d

        self.memo[key] = (total_val, total_len)
        return (total_val, total_len)

    def concat_numbers(self, a, a_len, b, b_len):
        """Concatenate two values respecting their string lengths"""
        return (a * pow(10, b_len, MOD) + b) % MOD, a_len + b_len

    def parse_term(self):
        """<term> ::= <number> | <number> '-' <number> | <number> '(' <expression> ')'"""
        l, l_len = self.get_number()

        result_val = l
        result_len = l_len

        if self.peek() == '-':
            self.pos[0] += 1
            r, _ = self.get_number()
            val, len_range = self.range_concat(l, r)
            result_val, result_len = val, len_range
        elif self.peek() == '(':
            self.pos[0] += 1  # skip '('
            exp_val, exp_len = self.parse_expr()
            self.pos[0] += 1 if self.peek() == ')' else 0
            if self.peek() == ')':
                self.pos[0] += 1
            val, len_rep = self.repeat_val(result_val, exp_val, exp_len)
            result_val, result_len = val, len_rep

        return result_val, result_len

    def parse_expr(self):
        """<expression> ::= <term> | <expression> '+' <term>"""
        term_val, term_len = self.parse_term()

        while self.peek() == '+':
            self.pos[0] += 1
            term_val2, term_len2 = self.parse_term()
            term_val, term_len = self.concat_numbers(term_val, term_len, term_val2, term_len2)

        return term_val, term_len

    def solve(self):
        term_val, term_len = self.parse_expr()
        return str(term_val)

def solution(s):
    if not s or not s.strip():
        return "0"
    parser = ExpressionParser(s.strip())
    return parser.solve()

